steps.script:
try {
 $files=@(Get-ChildItem (Join-Path $env:LOCALAPPDATA 'TT_Recuperacion') -Filter 'editorial-rescue-*.log' -ErrorAction Stop | Sort-Object LastWriteTime -Descending | Select-Object -First 1)
 $lines=@()
 if($files.Count){$lines=@(Get-Content $files[0].FullName -Tail 22)}
 $o=@{state='ok';file=($files|Select-Object -First 1 -ExpandProperty Name);lines=$lines}
 Write-Output ('TTRESULT:'+($o|ConvertTo-Json -Compress -Depth 4))
}catch{Write-Output ('TTRESULT:'+(@{state='error';reason=[string]$_.Exception.Message}|ConvertTo-Json -Compress))}
